from collections import Counter
import itertools, json

# The attention circuit reduces to the public weighted score:
# symbol 0 contributes 2, symbol 1 contributes 1, and symbol 2 contributes 0.
counts = Counter()
for length in range(1, 6):
    for seq in itertools.product(range(3), repeat=length):
        counts[sum(2 if s == 0 else 1 if s == 1 else 0 for s in seq)] += 1
total = sum(counts.values())
assert total == 363

def threshold(score):
    return 0 if score < 3 else 1 if score < 7 else 2

def mod(score):
    return score % 3

def scaled_readout(score):
    # Scaling the output feature moves the score through the same readout.
    return round(0.67 * score)

def fraction_changed(before, after):
    return sum(n for score, n in counts.items()
               if before(score) != after(score)) / total

sub = {"effects": {
    "f0": [0.0, 0.0],
    "f1": [
        fraction_changed(threshold, lambda s: threshold(0.67 * s)),
        fraction_changed(mod, lambda s: mod(scaled_readout(s))),
    ],
    "f2": [0.0, fraction_changed(mod, lambda s: 0)],
    "f3": [
        fraction_changed(threshold, lambda s: 0),
        fraction_changed(mod, lambda s: mod(scaled_readout(s))),
    ],
}}

check_submission(sub)
with open("/work/submission.json", "w") as f:
    json.dump(sub, f)
